#include <stdio.h>

int main() {
    FILE *fp = fopen("missing.txt", "r");
    if (fp == NULL) {
        printf("Could not open file\n");
        return 1;
    }
    char buffer[100];
    fgets(buffer, sizeof(buffer), fp);
    printf("%s\n", buffer);
    fclose(fp);
    return 0;
}
